"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["15655"],{66989(e){e.exports=JSON.parse('{"id":"FUT-0049","slug":"ebitda","term":"EBITDA","also_known_as":["Earnings Before Interest","Taxes","Depreciation and Amortization"],"difficulty":"Intermediate","definition":"EBITDA stands for earnings before interest, taxes, depreciation and amortization. It measures a company\'s profit from operations before financing costs, taxes and non-cash charges for the wearing out of assets.","explanation":["EBITDA starts with operating profit, or EBIT, and adds back depreciation and amortization. Because these are non-cash expenses, EBITDA is often used as a rough indicator of the cash a business\'s operations generate.","For example, a company with EBIT of 8 million, depreciation of 3 million and amortization of 1 million has EBITDA of 12 million.","EBITDA is popular for comparing companies, because it removes differences caused by debt levels, tax rates and accounting choices about depreciation. It is widely used in valuation, as in the EV/EBITDA multiple, and in loan agreements, which often limit borrowing to a multiple of EBITDA.","It has important limitations. Depreciation reflects a real cost: machinery and buildings eventually have to be replaced. EBITDA also ignores changes in working capital, interest and taxes, which all use real cash. Companies sometimes report \\"adjusted EBITDA\\" that excludes further costs, so it is worth checking exactly what has been left out."],"note":"","total":1500,"prev":{"slug":"ebit","term":"EBIT"},"next":{"slug":"ebitda-margin","term":"EBITDA Margin"}}')}}]);